import Foundation

/// 대한민국 도시철도 순서·역명·좌표 카탈로그.
/// 국토교통부 도시철도 전체노선 표준자료를 기본으로 하고, 좌표가 없는 역은
/// CC0 공개 역 목록으로 보완한다. 원본 센서가 아니라 경로를 그리기 위한
/// 정적 파생자료이므로 로그와 분리해 보관한다.
enum SubwayStationCatalog {
    struct Station: Hashable, Sendable {
        let lineName: String
        let order: Int
        let stationName: String
        let latitude: Double?
        let longitude: Double?

        var coordinate: GeoPoint? {
            guard let latitude, let longitude else { return nil }
            return GeoPoint(
                latitude: latitude,
                longitude: longitude,
                altitude: 0,
                horizontalAccuracy: -1,
                verticalAccuracy: -1
            )
        }
    }

    struct CoordinateTrajectory: Hashable, Sendable {
        let observedStationNames: [String]
        let route: SubwayRoutePath
        let span: TimeSpan
        /// 지하 구간에서 GPS가 끊겨 출발·도착역만 남은 제한적 복원입니다.
        /// 호출부에서 별도의 철도 지도 신호를 반드시 함께 확인합니다.
        let isSparseEndpointTrajectory: Bool
    }

    struct StationStopPattern: Hashable, Sendable {
        let observedStationNames: [String]
        let stoppedStationNames: [String]

        var observedStationCount: Int { observedStationNames.count }
        var stoppedStationCount: Int { stoppedStationNames.count }

        /// GPS 표본이 성긴 배터리 절약 모드에서도 세 역 이상에서 정차가
        /// 확인된 경우만 강한 패턴으로 취급한다. 역 하나의 저속 표본만으로
        /// 자동차를 지하철로 바꾸지 않는다.
        var isStrong: Bool {
            observedStationCount >= 3
                && stoppedStationCount >= min(3, observedStationCount)
        }
    }

    /// A station stay derived from precise location samples.  This is kept
    /// separate from the raw sensor record so a route decision never rewrites
    /// the original GPS stream.
    struct StationStay: Codable, Hashable, Sendable {
        let stationName: String
        let arrival: Date
        let departure: Date
        let exitDistanceMeters: Double
        let exitConfirmed: Bool

        var duration: TimeInterval {
            max(0, departure.timeIntervalSince(arrival))
        }
    }

    /// The station-state result used by the classifier and the detail view.
    /// A result is confirmed only after the final station has been left by at
    /// least 50 m with a second outside sample proving continued movement.
    struct StationJourney: Codable, Hashable, Sendable {
        let stays: [StationStay]
        let route: SubwayRoutePath
        let startStationName: String
        let transferStationNames: [String]
        let destinationStationName: String
        let span: TimeSpan
        let isConfirmed: Bool
        /// Separate corroboration hook for the caller.  Station geometry and
        /// dwell alone must not override a car/bus classification.
        let hasRailEvidence: Bool
        let evidence: [String]

        var stationNames: [String] {
            stays.map(\.stationName)
        }
    }

    /// GPS가 끊긴 지하 구간에서 역 도착 시각과 역 좌표만으로 지도에
    /// 표시할 임시 위치입니다. 원본 `SensorReading`을 대체하거나
    /// archive에 다시 기록하지 않고, 호출자가 표시 계층에서만 사용합니다.
    struct TemporaryLocation: Identifiable, Codable, Hashable, Sendable {
        let id: UUID
        let timestamp: Date
        let stationName: String
        let point: GeoPoint
        let reason: String

        init(
            id: UUID = UUID(),
            timestamp: Date,
            stationName: String,
            point: GeoPoint,
            reason: String = "지하철역 도착 시각 기반 임시 위치"
        ) {
            self.id = id
            self.timestamp = timestamp
            self.stationName = stationName
            self.point = point
            self.reason = reason
        }
    }

    private static let packedRoutes = ""

    static let stations: [Station] = decodeStations()

    private struct StationSpatialCell: Hashable {
        let latitude: Int
        let longitude: Int
    }

    private static let stationSpatialCellDegrees = 0.01
    private static let stationSpatialIndex: [StationSpatialCell: [Int]] = {
        stations.indices.reduce(into: [:]) { result, index in
            guard let coordinate = stations[index].coordinate else {
                return
            }
            let cell = StationSpatialCell(
                latitude: Int(floor(
                    coordinate.latitude / stationSpatialCellDegrees
                )),
                longitude: Int(floor(
                    coordinate.longitude / stationSpatialCellDegrees
                ))
            )
            result[cell, default: []].append(index)
        }
    }()

    private static let stationIndices: [String: [Int]] = {
        Dictionary(grouping: stations.indices) {
            normalized(stations[$0].stationName)
        }
    }()

    private static let adjacency: [[Int]] = {
        var edges = Array(repeating: Set<Int>(), count: stations.count)
        let byLine = Dictionary(grouping: stations.indices) {
            stations[$0].lineName
        }
        for indices in byLine.values {
            let ordered = indices.sorted {
                stations[$0].order < stations[$1].order
            }
            for pair in zip(ordered, ordered.dropFirst()) {
                edges[pair.0].insert(pair.1)
                edges[pair.1].insert(pair.0)
            }
        }

        // 같은 역 이름을 공유하는 노선은 환승 간선으로 연결한다.
        for indices in stationIndices.values {
            for first in indices {
                for second in indices where first < second {
                    guard stations[first].lineName != stations[second].lineName
                    else { continue }
                    edges[first].insert(second)
                    edges[second].insert(first)
                }
            }
        }
        return edges.map(Array.init)
    }()

    static func stationNames(from readings: [SensorReading]) -> [String] {
        var names: [String] = []
        for reading in readings.sorted(by: { $0.timestamp < $1.timestamp }) {
            var name: String?
            if reading.matchesRailRoute {
                name = reading.nearbyStationName
            }
            if name == nil,
               reading.nearbyStation,
               !reading.matchesPublicTransitRoute {
                name = reading.nearbyStationName
            }
            if name == nil, reading.matchesRailRoute {
                name = reading.point.flatMap {
                    nearest(to: $0, maximumDistanceMeters: 450)?.stationName
                }
            }
            guard let name else { continue }
            let cleaned = name.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !cleaned.isEmpty,
                  stationIndices[normalized(cleaned)] != nil,
                  names.last.map({ normalized($0) }) != normalized(cleaned)
            else { continue }
            names.append(cleaned)
        }
        return names
    }

    /// GPS를 얻지 못한 표본이 역 도착 시각과 역명을 갖고 있을 때, 노선의
    /// 공식 역 좌표를 이용해 표시 전용 임시 위치를 만든다. 같은 역의
    /// 연속 표본은 첫 도착 시각 하나로 합친다.
    static func temporaryLocations(
        from readings: [SensorReading],
        route: SubwayRoutePath? = nil
    ) -> [TemporaryLocation] {
        let ordered = readings.sorted { $0.timestamp < $1.timestamp }
        let resolvedRoute = route ?? {
            let names = stationNames(from: ordered)
            guard names.count >= 2 else { return nil }
            return self.route(for: names)
        }()
        let candidateStops: [(stationName: String, point: GeoPoint)]
        if let resolvedRoute, isValid(resolvedRoute) {
            candidateStops = resolvedRoute.stops.compactMap { stop in
                guard let point = stop.coordinate else { return nil }
                return (stop.stationName, point)
            }
        } else {
            // A single station arrival is still a useful temporary anchor
            // when the next station has not produced a reading yet.
            candidateStops = stations.compactMap { station in
                guard let point = station.coordinate else { return nil }
                return (station.stationName, point)
            }
        }

        var result: [TemporaryLocation] = []
        for reading in ordered {
            guard reading.point == nil
                    || reading.locationFixQuality == .approximate
                    || !reading.gpsAvailable,
                  reading.nearbyStation || reading.matchesRailRoute,
                  let observedName = reading.nearbyStationName else {
                continue
            }
            let key = normalized(observedName)
            guard let stop = candidateStops.first(where: {
                normalized($0.stationName) == key
            }) else { continue }
            guard result.last.map({ normalized($0.stationName) }) != key else {
                continue
            }
            result.append(
                TemporaryLocation(
                    timestamp: reading.timestamp,
                    stationName: stop.stationName,
                    point: stop.point
                )
            )
        }
        return result
    }

    /// 사용자 등록 지하철역을 원본 좌표의 시간 순서로 역 이름에 매핑한다.
    /// 이름이 카탈로그와 달라도 등록 좌표가 공식 역 좌표에 가까우면
    /// 카탈로그 이름으로 정규화해 노선·환승 계산에 사용할 수 있다.
    static func userStationNames(
        from readings: [SensorReading],
        locations: [UserTransitLocation]
    ) -> [String] {
        let stations = locations.filter { $0.kind == .subwayStation }
        guard !stations.isEmpty else { return [] }

        var names: [String] = []
        for reading in readings.sorted(by: { $0.timestamp < $1.timestamp }) {
            guard let point = reading.point else { continue }
            guard let location = stations.min(by: {
                distanceMeters(point, $0.point) < distanceMeters(point, $1.point)
            }) else { continue }
            let radius = location.radiusMeters.isFinite && location.radiusMeters > 0
                ? location.radiusMeters
                : 100
            guard distanceMeters(point, location.point) <= radius else { continue }

            let stationName = nearest(
                to: location.point,
                maximumDistanceMeters: 450
            )?.stationName ?? location.name
            let cleanName = stationName.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !cleanName.isEmpty,
                  stationIndices[normalized(cleanName)] != nil,
                  names.last.map({ normalized($0) }) != normalized(cleanName)
            else { continue }
            names.append(cleanName)
        }
        return names
    }

    /// 노선의 출발·환승·도착 지점 중 사용자 등록 지하철역과 일치하는
    /// 지점을 반환한다. 이름 또는 등록 좌표로 비교한다.
    static func userStationRouteMatches(
        route: SubwayRoutePath,
        locations: [UserTransitLocation]
    ) -> [String] {
        let stations = locations.filter { $0.kind == .subwayStation }
        guard !stations.isEmpty,
              let first = route.stops.first,
              let last = route.stops.last else { return [] }

        var pointNames = [first.stationName]
        pointNames.append(contentsOf: route.transferStationNames)
        if normalized(pointNames.last ?? "") != normalized(last.stationName) {
            pointNames.append(last.stationName)
        }

        return pointNames.filter { name in
            let routeStops = route.stops.filter {
                normalized($0.stationName) == normalized(name)
            }
            return stations.contains { location in
                let locationNameMatches = normalized(location.name) == normalized(name)
                let radius = location.radiusMeters.isFinite && location.radiusMeters > 0
                    ? location.radiusMeters
                    : 100
                let coordinateMatches = routeStops.contains { stop in
                    guard let coordinate = stop.coordinate else { return false }
                    return distanceMeters(location.point, coordinate) <= radius
                }
                return locationNameMatches || coordinateMatches
            }
        }
    }

    /// 노선에 포함된 역 주변에서 `가다 → 서다 → 다시 가다`가 반복되는지
    /// 계산한다. 원본 GPS·Core Motion 표본은 건드리지 않고, 분류에 필요한
    /// 파생 근거만 반환한다.
    static func stationStopPattern(
        from readings: [SensorReading],
        route: SubwayRoutePath,
        maximumDistanceMeters: Double = 450
    ) -> StationStopPattern {
        let ordered = readings.sorted { $0.timestamp < $1.timestamp }
        guard !ordered.isEmpty else {
            return StationStopPattern(
                observedStationNames: [],
                stoppedStationNames: []
            )
        }
        let routeNames = Set(route.stops.map { normalized($0.stationName) })
        var observations: [(name: String, reading: SensorReading)] = []
        for reading in ordered {
            guard let name = stationName(
                for: reading,
                route: route,
                routeNames: routeNames,
                maximumDistanceMeters: maximumDistanceMeters
            ) else { continue }
            if let last = observations.last,
               normalized(last.name) == normalized(name) {
                observations[observations.count - 1] = (name, reading)
            } else {
                observations.append((name, reading))
            }
        }

        var observed: [String] = []
        var stopped: [String] = []
        for (index, observation) in observations.enumerated() {
            let name = observation.name
            guard observed.last.map({ normalized($0) })
                    != normalized(name) else { continue }
            observed.append(name)
            let previous = index > 0 ? observations[index - 1].reading : nil
            let next = index + 1 < observations.count
                ? observations[index + 1].reading
                : nil
            if isStationStop(
                observation.reading,
                previous: previous,
                next: next
            ) {
                stopped.append(name)
            }
        }
        return StationStopPattern(
            observedStationNames: observed,
            stoppedStationNames: stopped
        )
    }

    /// Infers the station-state machine requested by the transit rules:
    /// 5-minute station stay -> departure, optional 5-minute transfer stay ->
    /// continued departure, then a final 5-minute stay followed by a 50 m
    /// exit.  The last exit is deliberately required before the result is
    /// marked confirmed so a train that has merely arrived is not presented as
    /// a completed trip.  This is a derived evidence hook; callers still need
    /// rail or Wi-Fi corroboration before changing a travel mode.
    static func stationJourney(
        from readings: [SensorReading],
        minimumStayDuration: TimeInterval = 5 * 60,
        exitDistanceMeters: Double = 50
    ) -> StationJourney? {
        let ordered = readings.sorted { $0.timestamp < $1.timestamp }
        let samples: [StationPointSample] = ordered.compactMap { reading in
            guard let point = reading.point,
                  reading.locationFixQuality != .approximate,
                  point.horizontalAccuracy > 0,
                  point.horizontalAccuracy <= 100 else {
                return nil
            }
            // GPS 표본은 역 중심에서 수십~수백 m 벗어날 수 있다. 체류
            // 판정은 보행 출입구까지 포함하되, 실제 승차 종료는 아래의
            // 50m 이탈 표본 두 개로 별도 확정한다.
            let station = nearest(
                to: point,
                maximumDistanceMeters: max(220, exitDistanceMeters)
            )
            return StationPointSample(
                stationName: station?.stationName,
                timestamp: reading.timestamp,
                point: point
            )
        }
        guard !samples.isEmpty,
              minimumStayDuration.isFinite,
              minimumStayDuration >= 0,
              exitDistanceMeters.isFinite,
              exitDistanceMeters > 0 else {
            return nil
        }

        var candidateStays: [StationStay] = []
        var index = 0
        while index < samples.count {
            guard let stationName = samples[index].stationName else {
                index += 1
                continue
            }
            let normalizedName = normalized(stationName)
            var end = index
            while end + 1 < samples.count,
                  let nextName = samples[end + 1].stationName,
                  normalized(nextName) == normalizedName {
                end += 1
            }

            let arrival = samples[index].timestamp
            let departure = samples[end].timestamp
            let duration = departure.timeIntervalSince(arrival)
            if duration >= minimumStayDuration,
               let coordinate = coordinate(for: stationName) {
                let after = samples[(end + 1)...]
                let outsideDistances = after.compactMap { sample -> Double? in
                    let distance = distanceMeters(sample.point, coordinate)
                    return distance >= exitDistanceMeters ? distance : nil
                }
                let exitDistance = outsideDistances.max() ?? 0
                // Two outside fixes prevent a single GPS spike from closing a
                // candidate.  A subsequent station stay naturally contributes
                // several outside fixes when the next state is observed.
                let exitConfirmed = outsideDistances.count >= 2
                candidateStays.append(
                    StationStay(
                        stationName: stationName,
                        arrival: arrival,
                        departure: departure,
                        exitDistanceMeters: exitDistance,
                        exitConfirmed: exitConfirmed
                    )
                )
            }
            index = end + 1
        }

        // A second stay at the same station after a missing/non-stationary
        // interval is a new state.  Route validation below rejects a loop,
        // while preserving the original order for a legitimate transfer.
        guard candidateStays.count >= 2,
              candidateStays.allSatisfy(\.exitConfirmed),
              let first = candidateStays.first,
              let last = candidateStays.last,
              normalized(first.stationName) != normalized(last.stationName) else {
            return nil
        }
        let names = candidateStays.map(\.stationName)
        guard let route = route(for: names), isValid(route) else { return nil }
        let transferNames = route.transferStationNames
        let span = TimeSpan(start: first.arrival, end: last.departure)
        let railMatchCount = ordered.filter(\.matchesRailRoute).count
        let railRatio = ordered.isEmpty
            ? 0
            : Double(railMatchCount) / Double(ordered.count)
        let hasRailEvidence = railMatchCount >= 2 && railRatio >= 0.25
            || SubwayWiFiSSID.hasContinuousEvidence(
                ordered.map(\.connectedWiFiSSID)
            )
        let hasVerticalStationEvidence = hasVerticalStationEvidence(
            in: ordered
        )
        var evidence = candidateStays.map {
            "역 \($0.stationName) 5분 이상 체류"
        }
        evidence.append("역 이탈 50m 이상 지속")
        evidence.append("출발역·환승역·도착역 상태 확정")
        if hasRailEvidence {
            evidence.append("철도 경로 또는 지하철 Wi-Fi 보조 확인")
        }
        if hasVerticalStationEvidence {
            evidence.append("역 근방 수직 이동·고도 변화 보조 관측")
        }
        if !transferNames.isEmpty {
            evidence.append("환승 " + transferNames.joined(separator: ", "))
        }
        return StationJourney(
            stays: candidateStays,
            route: route,
            startStationName: first.stationName,
            transferStationNames: transferNames,
            destinationStationName: last.stationName,
            span: span,
            isConfirmed: true,
            hasRailEvidence: hasRailEvidence,
            evidence: evidence
        )
    }

    private struct StationPointSample {
        let stationName: String?
        let timestamp: Date
        let point: GeoPoint
    }

    private static func coordinate(for stationName: String) -> GeoPoint? {
        let key = normalized(stationName)
        return stations.first {
            normalized($0.stationName) == key
        }?.coordinate
    }

    private static func hasVerticalStationEvidence(
        in readings: [SensorReading]
    ) -> Bool {
        for pair in zip(readings, readings.dropFirst()) {
            guard pair.1.timestamp.timeIntervalSince(pair.0.timestamp) <= 15 * 60,
                  let change = AltitudeDelta.between(
                    AltitudeDelta.Sample(pair.0),
                    and: AltitudeDelta.Sample(pair.1)
                  ),
                  change.source != .gps,
                  abs(change.meters) >= 3 else {
                continue
            }
            return true
        }
        return false
    }

    private static func stationName(
        for reading: SensorReading,
        route: SubwayRoutePath,
        routeNames: Set<String>,
        maximumDistanceMeters: Double
    ) -> String? {
        if reading.matchesRailRoute,
           let named = reading.nearbyStationName {
            let normalizedName = normalized(named)
            if routeNames.contains(normalizedName) {
                return route.stops.first {
                    normalized($0.stationName) == normalizedName
                }?.stationName
            }
        }
        guard let point = reading.point else { return nil }
        var nearest: (name: String, distance: Double)?
        for stop in route.stops {
            guard let coordinate = stop.coordinate else { continue }
            let distance = distanceMeters(point, coordinate)
            guard distance <= maximumDistanceMeters else { continue }
            if nearest.map({ distance < $0.distance }) ?? true {
                nearest = (stop.stationName, distance)
            }
        }
        return nearest?.name
    }

    private static func isStationStop(
        _ reading: SensorReading,
        previous: SensorReading?,
        next: SensorReading?
    ) -> Bool {
        if reading.frequentStops || reading.motion == .stationary {
            return true
        }
        if let speed = reading.speedMetersPerSecond,
           speed.isFinite,
           speed <= 2.5 {
            return true
        }
        // 역 표본 하나가 저속으로 저장되지 않은 경우에도 앞뒤 표본이
        // 충분히 빠르면 역에서 감속·정차한 것으로 본다.
        let previousSpeed = previous.flatMap { speed(of: $0) }
        let nextSpeed = next.flatMap { speed(of: $0) }
        let currentSpeed = speed(of: reading)
        if let currentSpeed,
           currentSpeed <= 4,
           (previousSpeed ?? 0) >= 7 || (nextSpeed ?? 0) >= 7 {
            return true
        }
        return false
    }

    private static func speed(of reading: SensorReading) -> Double? {
        if let speed = reading.speedMetersPerSecond,
           speed.isFinite,
           speed >= 0 {
            return speed
        }
        return nil
    }

    /// 과거 기록에는 지도 보강 값이 저장되지 않은 경우가 있다. 원본 좌표를
    /// 바꾸지 않고, 정확한 좌표가 세 곳 이상의 서로 다른 역을 시간 순서대로
    /// 통과한 경우에만 파생 철도 궤적으로 복원한다.
    static func coordinateTrajectory(
        from readings: [SensorReading],
        maximumDistanceMeters: Double = 450
    ) -> CoordinateTrajectory? {
        trajectory(
            from: readings,
            maximumDistanceMeters: maximumDistanceMeters,
            minimumObservedStationCount: 3,
            minimumDuration: 2 * 60,
            minimumRouteStopCount: 3,
            isSparseEndpointTrajectory: false
        )
    }

    /// 터널 안에서 GPS가 끊겨 두 역만 남은 경우를 위한 제한적 보조 궤적입니다.
    /// 이 함수의 결과만으로는 지하철로 확정하지 않으며, 호출부가
    /// `matchesRailRoute` 같은 별도 철도 신호를 함께 요구해야 합니다.
    static func sparseEndpointTrajectory(
        from readings: [SensorReading],
        maximumDistanceMeters: Double = 220
    ) -> CoordinateTrajectory? {
        trajectory(
            from: readings,
            maximumDistanceMeters: maximumDistanceMeters,
            minimumObservedStationCount: 2,
            minimumDuration: 8 * 60,
            minimumRouteStopCount: 4,
            isSparseEndpointTrajectory: true
        )
    }

    private static func trajectory(
        from readings: [SensorReading],
        maximumDistanceMeters: Double,
        minimumObservedStationCount: Int,
        minimumDuration: TimeInterval,
        minimumRouteStopCount: Int,
        isSparseEndpointTrajectory: Bool
    ) -> CoordinateTrajectory? {
        var observations: [(
            name: String,
            timestamp: Date,
            point: GeoPoint
        )] = []
        for reading in readings.sorted(by: { $0.timestamp < $1.timestamp }) {
            guard let point = reading.point,
                  point.horizontalAccuracy < 0
                    || point.horizontalAccuracy <= 100,
                  let station = nearest(
                      to: point,
                      maximumDistanceMeters: maximumDistanceMeters
                  ) else { continue }
            let name = station.stationName
            guard observations.last.map({ normalized($0.name) })
                    != normalized(name) else { continue }

            // 한두 GPS 표본이 인접 역으로 튀었다가 곧 돌아오는 A-B-A 잡음은
            // 실제 역 통과로 세지 않는다.
            if observations.count >= 2,
               normalized(observations[observations.count - 2].name)
                    == normalized(name) {
                observations.removeLast()
                continue
            }
            observations.append((name, reading.timestamp, point))
        }

        // 승차가 끝난 뒤 회사·집까지 걷다가 인접 역 반경을 한 번 더 스치는
        // 경우가 있다. 앞선 역 사이는 철도 속도인데 마지막 역만 보행 속도면
        // 그 마지막 표본은 노선 종점이 아니라 도착 후 보행으로 본다.
        while observations.count >= 4,
              hasRailSpeedLeg(in: Array(observations.dropLast())),
              let penultimate = observations.dropLast().last,
              let last = observations.last,
              legSpeed(from: penultimate, to: last) < 3.2 {
            observations.removeLast()
        }

        // 하루 전체 표본을 한 번에 읽으면 출근·퇴근과 도로 주행이 하나의
        // 경로로 이어질 수 있다. 관측 역의 연속 구간을 모두 평가하고,
        // 실제 노선상 이동 거리가 가장 긴 단순 경로를 선택한다. 역을 다시
        // 방문하는 후보는 도로를 따라 여러 역 반경을 스친 잡음일 가능성이
        // 높아 제외한다.
        let candidates = trajectoryCandidates(
            from: observations,
            minimumObservedStationCount: minimumObservedStationCount,
            minimumDuration: minimumDuration,
            minimumRouteStopCount: minimumRouteStopCount
        )
        guard let best = candidates.max(by: { lhs, rhs in
            if lhs.route.stops.count != rhs.route.stops.count {
                return lhs.route.stops.count < rhs.route.stops.count
            }
            if lhs.names.count != rhs.names.count {
                return lhs.names.count < rhs.names.count
            }
            return lhs.last.timestamp < rhs.last.timestamp
        }) else {
            return nil
        }
        return CoordinateTrajectory(
            observedStationNames: best.names,
            route: best.route,
            span: TimeSpan(start: best.first.timestamp, end: best.last.timestamp),
            isSparseEndpointTrajectory: isSparseEndpointTrajectory
        )
    }

    private static func trajectoryCandidates(
        from observations: [(
            name: String,
            timestamp: Date,
            point: GeoPoint
        )],
        minimumObservedStationCount: Int,
        minimumDuration: TimeInterval,
        minimumRouteStopCount: Int
    ) -> [(
        names: [String],
        route: SubwayRoutePath,
        first: (name: String, timestamp: Date, point: GeoPoint),
        last: (name: String, timestamp: Date, point: GeoPoint)
    )] {
        guard observations.count >= minimumObservedStationCount else { return [] }
        var result: [(
            names: [String],
            route: SubwayRoutePath,
            first: (name: String, timestamp: Date, point: GeoPoint),
            last: (name: String, timestamp: Date, point: GeoPoint)
        )] = []
        for start in observations.indices {
            let firstEnd = start + minimumObservedStationCount - 1
            guard firstEnd < observations.count else { continue }
            for end in firstEnd..<observations.count {
                let window = Array(observations[start...end])
                let names = window.map(\.name)
                guard Set(names.map(normalized)).count >= minimumObservedStationCount,
                      let first = window.first,
                      let last = window.last,
                      last.timestamp.timeIntervalSince(first.timestamp)
                        >= minimumDuration,
                      let route = route(for: names),
                      route.stops.count >= minimumRouteStopCount,
                      route.stops.count
                        <= min(64, max(12, names.count * 8)),
                      !hasNonAdjacentStationRepeat(route) else {
                    continue
                }
                result.append((names, route, first, last))
            }
        }
        return result
    }

    private static func hasNonAdjacentStationRepeat(
        _ route: SubwayRoutePath
    ) -> Bool {
        var lastIndexByName: [String: Int] = [:]
        for (index, stop) in route.stops.enumerated() {
            let name = normalized(stop.stationName)
            if let previous = lastIndexByName[name], index - previous > 1 {
                return true
            }
            lastIndexByName[name] = index
        }
        return false
    }

    private static func hasRailSpeedLeg(
        in observations: [(name: String, timestamp: Date, point: GeoPoint)]
    ) -> Bool {
        zip(observations, observations.dropFirst()).contains {
            legSpeed(from: $0.0, to: $0.1) >= 4
        }
    }

    private static func legSpeed(
        from: (name: String, timestamp: Date, point: GeoPoint),
        to: (name: String, timestamp: Date, point: GeoPoint)
    ) -> Double {
        let elapsed = max(1, to.timestamp.timeIntervalSince(from.timestamp))
        return distanceMeters(from.point, to.point) / elapsed
    }

    static func nearest(
        to point: GeoPoint,
        maximumDistanceMeters: Double = 450
    ) -> Station? {
        guard point.latitude.isFinite,
              point.longitude.isFinite,
              maximumDistanceMeters.isFinite,
              maximumDistanceMeters >= 0 else {
            return nil
        }
        let latitudeRadius = maximumDistanceMeters / 111_000
        let longitudeMetersPerDegree = max(
            1,
            111_000 * cos(point.latitude * .pi / 180)
        )
        let longitudeRadius = maximumDistanceMeters
            / longitudeMetersPerDegree
        let minimumLatitudeCell = Int(floor(
            (point.latitude - latitudeRadius) / stationSpatialCellDegrees
        ))
        let maximumLatitudeCell = Int(floor(
            (point.latitude + latitudeRadius) / stationSpatialCellDegrees
        ))
        let minimumLongitudeCell = Int(floor(
            (point.longitude - longitudeRadius) / stationSpatialCellDegrees
        ))
        let maximumLongitudeCell = Int(floor(
            (point.longitude + longitudeRadius) / stationSpatialCellDegrees
        ))
        var best: (station: Station, distance: Double)?
        for latitudeCell in minimumLatitudeCell...maximumLatitudeCell {
            for longitudeCell in minimumLongitudeCell...maximumLongitudeCell {
                let cell = StationSpatialCell(
                    latitude: latitudeCell,
                    longitude: longitudeCell
                )
                for index in stationSpatialIndex[cell] ?? [] {
                    let station = stations[index]
                    guard let coordinate = station.coordinate else { continue }
                    let distance = distanceMeters(point, coordinate)
                    guard distance <= maximumDistanceMeters else { continue }
                    if best.map({ distance < $0.distance }) ?? true {
                        best = (station, distance)
                    }
                }
            }
        }
        return best?.station
    }

    static func route(for readings: [SensorReading]) -> SubwayRoutePath? {
        route(for: stationNames(from: readings))
    }

    static func route(for observedNames: [String]) -> SubwayRoutePath? {
        let names = observedNames.map { normalized($0) }
            .filter { stationIndices[$0] != nil }
        guard names.count >= 2 else { return nil }

        var path: [Int] = []
        for pair in zip(names, names.dropFirst()) {
            guard let starts = stationIndices[pair.0],
                  let ends = stationIndices[pair.1],
                  let leg = shortestPath(from: starts, to: ends) else {
                continue
            }
            if path.isEmpty {
                path = leg
            } else {
                path.append(contentsOf: leg.dropFirst(path.last == leg.first ? 1 : 0))
            }
        }
        guard path.count >= 2 else { return nil }

        let stops = path.map { index in
            let station = stations[index]
            return SubwayRouteStop(
                lineName: station.lineName,
                order: station.order,
                stationName: station.stationName,
                latitude: station.latitude,
                longitude: station.longitude
            )
        }
        var lineNames: [String] = []
        var transfers: [String] = []
        for stop in stops {
            if lineNames.last != stop.lineName {
                lineNames.append(stop.lineName)
            }
        }
        for pair in zip(stops, stops.dropFirst()) where
            normalized(pair.0.stationName) == normalized(pair.1.stationName)
            && pair.0.lineName != pair.1.lineName {
            if transfers.last != pair.0.stationName {
                transfers.append(pair.0.stationName)
            }
        }
        // 서로 다른 출퇴근 구간을 역 이름만으로 이어 붙이면 노선이
        // 출발역으로 되돌아오는 순환 경로가 만들어질 수 있다. 실제 한 번의
        // 이동은 같은 역을 환승 접점에서 한 번(인접한 두 노선)만 반복할 수
        // 있으므로, 그 외의 반복 경로는 노선 불일치로 버린다.
        guard !hasNonAdjacentStationRepeat(
            SubwayRoutePath(
                stops: stops,
                lineNames: lineNames,
                transferStationNames: transfers
            )
        ) else {
            return nil
        }
        return SubwayRoutePath(
            stops: stops,
            lineNames: lineNames,
            transferStationNames: transfers
        )
    }

    static func bestRoute(_ routes: [SubwayRoutePath?]) -> SubwayRoutePath? {
        routes.compactMap { $0 }.max { lhs, rhs in
            routeScore(lhs) < routeScore(rhs)
        }
    }

    /// 저장된 파생 노선이 한 번의 이동으로 설명 가능한지 확인한다.
    /// 예전 버전이 출·퇴근 역 이름을 하루 전체로 이어 붙여 만든 순환
    /// 노선은 다음 갱신에서 다시 살아나지 않도록 여기서 제외한다.
    static func isValid(_ route: SubwayRoutePath) -> Bool {
        route.stops.count >= 2
            && !hasNonAdjacentStationRepeat(route)
    }

    private static func routeScore(_ route: SubwayRoutePath) -> Int {
        let repeatPenalty = hasNonAdjacentStationRepeat(route) ? 10_000 : 0
        return route.stops.count - repeatPenalty
    }

    private static func shortestPath(
        from starts: [Int],
        to ends: [Int]
    ) -> [Int]? {
        let destinations = Set(ends)
        var parents = Array(repeating: -1, count: stations.count)
        var queue: [Int] = []
        for start in starts where parents[start] == -1 {
            parents[start] = start
            queue.append(start)
        }
        var cursor = 0
        while cursor < queue.count {
            let current = queue[cursor]
            cursor += 1
            if destinations.contains(current) {
                var result: [Int] = []
                var node = current
                while parents[node] != node {
                    result.append(node)
                    node = parents[node]
                }
                result.append(node)
                return result.reversed()
            }
            for next in adjacency[current] where parents[next] == -1 {
                parents[next] = current
                queue.append(next)
            }
        }
        return nil
    }

    private static func normalized(_ value: String) -> String {
        var result = value.filter { !$0.isWhitespace }
        if result.hasSuffix("역") {
            result.removeLast()
        }
        return result
    }

    private static func decodeStations() -> [Station] {
        guard let data = Data(base64Encoded: packedRoutes),
              let text = String(data: data, encoding: .utf8) else {
            return []
        }
        return text.split(separator: "\n").compactMap { line in
            let fields = line.split(separator: "\t", omittingEmptySubsequences: false)
            guard fields.count == 5,
                  let order = Int(fields[1]) else { return nil }
            return Station(
                lineName: String(fields[0]),
                order: order,
                stationName: String(fields[2]),
                latitude: Double(fields[3]),
                longitude: Double(fields[4])
            )
        }
    }
}
